// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    // fuzz parameters: from address, uint256 v, uint256 _decimals, address[] memory _tos
    // The universal property: for any admissible input (we require _tos.length > 0 as the function does),
    // the reference C.transfer(...) does not revert (completes successfully). The mutant that iterates one
    // past the end may revert for some non-empty _tos. We assert that calling transfer returns (does not revert).
    function testFuzz_property(address from, uint256 v, uint256 _decimals, address[] memory _tos) public {
        // Keep domain admissible: function requires _tos.length > 0, so assume that.
        vm.assume(_tos.length > 0);
        // bound decimals to a reasonable range to avoid overflow in v * 10 ** _decimals
        _decimals = bound(_decimals, 0, 18);
        // also bound v to avoid overflow in multiplication (keep it wide but safe)
        v = bound(v, 0, type(uint256).max / (10 ** _decimals == 0 ? 1 : 10 ** _decimals));

        bool ok;
        try c.transfer(from, address(0x1234567890123456789012345678901234567890), _tos, v, _decimals) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference C never reverts for any admissible input (it iterates exactly _tos.length times).
        assertTrue(ok);
    }
}
